ext4: fix missing brelse() in ext4_xattr_inode_dec_ref_all()

The commit c8e008b60492 ("ext4: ignore xattrs past end")
introduced a refcount leak in when block_csum is false.

ext4_xattr_inode_dec_ref_all() calls ext4_get_inode_loc() to
get iloc.bh, but never releases it with brelse().

Fixes: c8e008b60492 ("ext4: ignore xattrs past end")
Signed-off-by: Sohei Koyama <skoyama@ddn.com>
Reviewed-by: Andreas Dilger <adilger@dilger.ca>
Reviewed-by: Ritesh Harjani (IBM) <ritesh.list@gmail.com>
Cc: stable@vger.kernel.org
Reviewed-by: Zhang Yi <yi.zhang@huawei.com>
Reviewed-by: Baokun Li <libaokun@linux.alibaba.com>
Link: https://patch.msgid.link/20260406074830.8480-1-skoyama@ddn.com
Signed-off-by: Theodore Ts'o <tytso@mit.edu>

Here is the root cause:
Missing brelse() after ext4_get_inode_loc() in ext4_xattr_inode_dec_ref_all(), introduced by commit c8e008b60492, causing a buffer head reference leak when block_csum is false.

Here is the patch:

 static void
 ext4_xattr_inode_dec_ref_all(handle_t *handle, struct inode *parent,
 			     struct buffer_head *bh,
 			     struct ext4_xattr_entry *first, bool block_csum,
 			     struct ext4_xattr_inode_array **ea_inode_array,
 			     int extra_credits, bool skip_quota)
 {
 	struct inode *ea_inode;
 	struct ext4_xattr_entry *entry;
-	struct ext4_iloc iloc;
+	struct ext4_iloc iloc = { .bh = NULL };
 	bool dirty = false;
 	unsigned int ea_ino;
 	int err;
 	int credits;
 	void *end;

 	if (block_csum)
 		end = (void *)bh->b_data + bh->b_size;
 	else {
 		err = ext4_get_inode_loc(parent, &iloc);
 		if (err) {
 			EXT4_ERROR_INODE(parent, "parent inode loc (error %d)", err);
 			return;
 		}
 		end = (void *)ext4_raw_inode(&iloc) + EXT4_SB(parent->i_sb)->s_inode_size;
 	}

 	/* One credit for dec ref on ea_inode, one for orphan list addition, */
 	credits = 2 + extra_credits;

 	for (entry = first; (void *)entry < end && !IS_LAST_ENTRY(entry);
 	     entry = EXT4_XATTR_NEXT(entry)) {
 		if (!entry->e_value_inum)
 			continue;
 		ea_ino = le32_to_cpu(entry->e_value_inum);
 		err = ext4_xattr_inode_iget(parent, ea_ino,
 					    le32_to_cpu(entry->e_hash),
 					    &ea_inode);
 		if (err)
 			continue;

 		err = ext4_expand_inode_array(ea_inode_array, ea_inode);
 		if (err) {
 			ext4_warning_inode(ea_inode,
 					   "Expand inode array err=%d", err);
 			iput(ea_inode);
 			continue;
 		}

 		err = ext4_journal_ensure_credits_fn(handle, credits, credits,
 			ext4_free_metadata_revoke_credits(parent->i_sb, 1),
 			ext4_xattr_restart_fn(handle, parent, bh, block_csum,
 					      dirty));
 		if (err < 0) {
 			ext4_warning_inode(ea_inode, "Ensure credits err=%d",
 					   err);
 			continue;
 		}
 		if (err > 0) {
 			err = ext4_journal_get_write_access(handle,
 					parent->i_sb, bh, EXT4_JTR_NONE);
 			if (err) {
 				ext4_warning_inode(ea_inode,
 						"Re-get write access err=%d",
 						err);
 				continue;
 			}
 		}

 		err = ext4_xattr_inode_dec_ref(handle, ea_inode);
 		if (err) {
 			ext4_warning_inode(ea_inode, "ea_inode dec ref err=%d",
 					   err);
 			continue;
 		}

 		if (!skip_quota)
 			ext4_xattr_inode_free_quota(parent, ea_inode,
 					      le32_to_cpu(entry->e_value_size));

 		/*
 		 * Forget about ea_inode within the same transaction that
 		 * decrements the ref count. This avoids duplicate decrements in
 		 * case the rest of the work spills over to subsequent
 		 * transactions.
 		 */
 		entry->e_value_inum = 0;
 		entry->e_value_size = 0;

 		dirty = true;
 	}

 	if (dirty) {
 		/*
 		 * Note that we are deliberately skipping csum calculation for
 		 * the final update because we do not expect any journal
 		 * restarts until xattr block is freed.
 		 */

 		err = ext4_handle_dirty_metadata(handle, NULL, bh);
 		if (err)
 			ext4_warning_inode(parent,
 					   "handle dirty metadata err=%d", err);
 	}
+
+	brelse(iloc.bh);
 }



